package buzz.walnutnest.bridge;
import android.app.Activity; import android.content.Intent; import android.os.Bundle; import android.provider.Settings; import android.view.Gravity; import android.widget.Button; import android.widget.LinearLayout; import android.widget.TextView;
public final class MainActivity extends Activity { @Override public void onCreate(Bundle state) { super.onCreate(state); startService(new Intent(this, BridgeService.class)); LinearLayout box=new LinearLayout(this); box.setOrientation(LinearLayout.VERTICAL); box.setGravity(Gravity.CENTER); box.setPadding(48,48,48,48); TextView title=new TextView(this); title.setText("Walnut Android Bridge\n\nA tiny pair of eyes and hands for Termux-MCP."); title.setTextSize(20); Button grant=new Button(this); grant.setText("Enable accessibility service"); grant.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS))); box.addView(title); box.addView(grant); setContentView(box); } }
